SELECT COUNT(*) AS payment_attempts
FROM payments
WHERE payment_date >= DATE '2026-02-01' AND payment_date < DATE '2026-03-01';

SELECT COUNT(*) AS payment_attempts_q1_by_payment_date
FROM payments
WHERE payment_date >= DATE '2026-01-01' AND payment_date < DATE '2026-04-01';

SELECT COUNT(*) AS n_orders, SUM(gross_amount) AS gross, SUM(discount_amount) AS discounts, SUM(gross_amount - discount_amount) AS net_all_orders
FROM orders
WHERE order_date >= DATE '2026-02-01' AND order_date < DATE '2026-03-01';

SELECT COUNT(*) AS n, SUM(p.amount) AS settled_payment_amount, SUM(o.gross_amount - o.discount_amount) AS settled_net_order_value
FROM orders o JOIN payments p ON p.order_id = o.order_id
WHERE o.order_date >= DATE '2026-02-01' AND o.order_date < DATE '2026-03-01' AND p.status='settled';

SELECT SUM(o.gross_amount - o.discount_amount) AS settled_by_payment_date_feb, COUNT(*)
FROM orders o JOIN payments p ON p.order_id=o.order_id
WHERE p.payment_date >= DATE '2026-02-01' AND p.payment_date < DATE '2026-03-01' AND p.status='settled';

SELECT SUM(o.gross_amount - o.discount_amount) AS settled_by_order_date_feb
FROM orders o JOIN payments p ON p.order_id=o.order_id
WHERE o.order_date >= DATE '2026-02-01' AND o.order_date < DATE '2026-03-01' AND p.status='settled';

SELECT
  MIN(p.payment_date) AS min_pay, MAX(p.payment_date) AS max_pay,
  MIN(r.refund_date) AS min_refund, MAX(r.refund_date) AS max_refund
FROM refunds r JOIN payments p ON r.payment_id=p.payment_id;
SELECT strftime('%Y-%m', r.refund_date) AS refund_month, COUNT(*) AS n, SUM(r.refund_amount) AS amt FROM refunds r GROUP BY 1 ORDER BY 1;

SELECT p.status, COUNT(*) AS n_refunds, SUM(r.refund_amount) AS refund_amt, SUM(p.amount) AS original_amt
FROM refunds r JOIN payments p ON p.payment_id = r.payment_id
GROUP BY p.status;
